def paragraph(body,anchor):
    chunks=re.findall(r'<p\b[^>]*>.*?</p>',body,re.S)or re.split(r'<br\s*/?>',body)
    matches=[impact.plain(x)for x in chunks if anchor in impact.plain(x)]
    assert matches,(anchor,body)
    return matches[0]
